	var translationKeys = Object.keys(translations).sort(function (a, b) { return b.length - a.length; });
	var locale = "zh-CN";
	try {
		locale = localStorage.getItem("viewer-locale") === "en" ? "en" : "zh-CN";
	} catch (e) {}
	function t(text) {
		if (locale !== "en") return text;
		// Most dynamic UI text is already English. Avoid scanning the full
		// translation table for every Vue/Element Plus update.
		if (typeof text !== "string" || !/[\u3400-\u9fff]/.test(text)) return text;
		if (translations[text]) return translations[text];
		var result = text;
		translationKeys.forEach(function (key) {
			if (key.length >= 4 && result.indexOf(key) >= 0) {
				result = result.split(key).join(translations[key]);
			}
		});
		return result;
	}
	function setLocale(value) {
		locale = value === "en" ? "en" : "zh-CN";
		try { localStorage.setItem("viewer-locale", locale); } catch (e) {}
		document.documentElement.lang = locale === "en" ? "en" : "zh-CN";
	}
	setLocale(locale);
	if (locale === "en" && document.title) document.title = t(document.title);
	window.ViewerI18n = { get locale() { return locale; }, t: t, setLocale: setLocale, translations: translations };
	if (locale === "en") {
		var observer = new MutationObserver(function (records) {
			records.forEach(function (record) {
				if (record.type === "characterData") {
					var target = record.target.parentElement;
					if (target && target.closest(".full-content, .log-text, code, pre, textarea, input, .metric, .mono")) return;
					var raw = record.target.nodeValue, value = raw.trim(), translated = t(value);
					if (translated !== value) record.target.nodeValue = raw.replace(value, translated);
					return;
				}
				record.addedNodes.forEach(function (node) {
					if (node.nodeType === 3) {
						var raw = node.nodeValue, value = raw.trim(), translated = t(value);
						if (translated !== value) node.nodeValue = raw.replace(value, translated);
					} else if (node.nodeType === 1) translateTree(node);
				});
			});
		});
		function translateTree(root) {
			function shouldTranslate(node) {
				var parent = node && node.parentElement;
				return !(parent && parent.closest(".full-content, .log-text, code, pre, textarea, input, .metric, .mono"));
			}
			function translateAttributes(el) {
				["placeholder", "title", "aria-label", "alt"].forEach(function (name) {
					var value = el.getAttribute && el.getAttribute(name);
					if (value) el.setAttribute(name, t(value));
				});
			}
			if (root.nodeType === 1) translateAttributes(root);
			var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
			var node;
			while ((node = walker.nextNode())) {
				if (!shouldTranslate(node)) continue;
				var raw = node.nodeValue, value = raw.trim(), translated = t(value);
				if (translated !== value) node.nodeValue = raw.replace(value, translated);
			}
			if (root.querySelectorAll) root.querySelectorAll("*").forEach(translateAttributes);
		}
		document.addEventListener("DOMContentLoaded", function () {
			translateTree(document.body);
			// Attributes are translated when their elements are added. Avoid
			// observing attribute writes: translating one would enqueue another
			// attribute mutation and can create a costly feedback loop.
			observer.observe(document.body, { childList: true, characterData: true, subtree: true });
		});
	}
